CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated NOLOGIN; END IF;
END
$$;

CREATE SCHEMA IF NOT EXISTS auth;
CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid
LANGUAGE sql STABLE AS $$
  SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid
$$;
GRANT USAGE ON SCHEMA auth TO anon,authenticated;
GRANT EXECUTE ON FUNCTION auth.uid() TO anon,authenticated;
GRANT USAGE ON SCHEMA public TO anon,authenticated;

CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE TABLE public.commercial_organizations(id uuid PRIMARY KEY);
CREATE TABLE public.commercial_organization_locations(
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id),
  state text NOT NULL DEFAULT 'active'
);
CREATE TABLE public.commercial_activities(
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id)
);
CREATE TABLE public.commercial_organization_members(
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id),
  user_id uuid NOT NULL REFERENCES auth.users(id),
  role text NOT NULL,
  state text NOT NULL,
  PRIMARY KEY(organization_id,user_id)
);
CREATE TABLE public.commercial_offerings(
  id uuid PRIMARY KEY,
  activity_id uuid NOT NULL REFERENCES public.commercial_activities(id),
  location_ref text NOT NULL
);
CREATE TABLE public.commercial_inventory_balances(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id),
  location_id uuid NOT NULL REFERENCES public.commercial_organization_locations(id),
  offering_id uuid NOT NULL REFERENCES public.commercial_offerings(id),
  quantity_on_hand numeric(20,6) NOT NULL CHECK(quantity_on_hand>=0),
  quantity_reserved numeric(20,6) NOT NULL DEFAULT 0 CHECK(quantity_reserved>=0 AND quantity_reserved<=quantity_on_hand),
  unit_cost_minor bigint CHECK(unit_cost_minor IS NULL OR unit_cost_minor>=0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(organization_id,location_id,offering_id)
);
CREATE TABLE public.commercial_inventory_costing_policies(
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id),
  location_id uuid,
  costing_method text NOT NULL CHECK(costing_method IN ('fifo','lifo','weighted_average'))
);
CREATE TABLE public.commercial_inventory_cost_layers(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES public.commercial_organizations(id),
  location_id uuid NOT NULL REFERENCES public.commercial_organization_locations(id),
  offering_id uuid NOT NULL REFERENCES public.commercial_offerings(id),
  source_type text NOT NULL CHECK(source_type IN ('opening_balance','purchase_receipt','adjustment')),
  source_ref text NOT NULL,
  received_at timestamptz NOT NULL DEFAULT now(),
  quantity_received numeric(20,6) NOT NULL CHECK(quantity_received>0),
  quantity_remaining numeric(20,6) NOT NULL CHECK(quantity_remaining>=0 AND quantity_remaining<=quantity_received),
  source_unit_cost_minor bigint NOT NULL CHECK(source_unit_cost_minor>=0),
  unit_cost_minor bigint NOT NULL CHECK(unit_cost_minor>=0),
  UNIQUE(organization_id,location_id,offering_id,source_ref)
);
CREATE TABLE public.commercial_stock_movements(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  offering_id uuid NOT NULL REFERENCES public.commercial_offerings(id),
  sale_id uuid,
  movement_type text NOT NULL CHECK(movement_type IN ('opening','sale','return','adjustment')),
  quantity_delta numeric(20,6) NOT NULL CHECK(quantity_delta<>0),
  source_ref text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid REFERENCES auth.users(id)
);
CREATE TABLE public.commercial_audit_events(
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id uuid,
  actor_user_id uuid,
  action text NOT NULL,
  entity_type text NOT NULL,
  entity_id text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.commercial_organization_members,
  public.commercial_organization_locations,
  public.commercial_inventory_balances,
  public.commercial_inventory_cost_layers,
  public.commercial_stock_movements TO authenticated;
